css:
.ss-doc {
	font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
	color: #1a1a1a;
	font-size: 12px;
	line-height: 1.45;
}
.ss-doc table { border-collapse: collapse; width: 100%; }
.ss-doc td, .ss-doc th { vertical-align: top; padding: 0; }
.ss-num { font-variant-numeric: tabular-nums; white-space: nowrap; }
.ss-right { text-align: right; }
.ss-label {
	font-size: 9.5px;
	letter-spacing: 0.1em;
	text-transform: uppercase;
	color: #757575;
	font-weight: bold;
}
.ss-head-rule { border-top: 2px solid #1a1a1a; margin-bottom: 16px; }
.section { margin-top: 0; }
.section:not(:first-child) { margin-top: 0; }
.custom-html { margin: 0; }
.ss-who td { padding-bottom: 16px; }
.ss-who .name { font-size: 15px; font-weight: bold; letter-spacing: -0.01em; }
.ss-who .sub { font-size: 10.5px; color: #757575; margin-top: 1px; }
.ss-who .period { font-size: 11.5px; font-weight: bold; margin-top: 1px; }
.ss-hero { background-color: #f2f2f2; }
.ss-hero td { padding: 16px 18px; }
.ss-hero .amt {
	font-size: 30px;
	font-weight: bold;
	line-height: 1.15;
	letter-spacing: -0.02em;
	white-space: nowrap;
	margin-top: 1px;
}
.ss-hero .words { font-size: 10.5px; color: #757575; margin-top: 4px; }
.ss-hero .pay {
	text-align: right;
	font-size: 10.5px;
	color: #444444;
	line-height: 1.65;
	white-space: nowrap;
}
.ss-hero .pay .ss-label { margin-bottom: 2px; }
.ss-ledger { margin-top: 22px; }
.ss-ledger col.amt { width: 30%; }
.ss-ledger td {
	padding: 6px 0;
	border-bottom: 1px solid #e2e2e2;
	font-size: 11.5px;
	text-align: right;
	color: #444444;
}
.ss-ledger td.c { text-align: left; }
.ss-ledger tr.ss-sec td {
	border-bottom: 1px solid #b0b0b0;
	border-top: 1px solid #b0b0b0;
	padding: 6px 0 5px;
	font-size: 9.5px;
	letter-spacing: 0.1em;
	text-transform: uppercase;
	color: #757575;
	font-weight: bold;
}
.ss-ledger tr.ss-sec.first td { border-top: none; padding-top: 0; }
.ss-ledger tr.ss-sec td.c { text-align: left; }
.ss-ledger tr.ss-sub td {
	border-bottom: none;
	border-top: 1px solid #b0b0b0;
	padding-top: 7px;
	padding-bottom: 14px;
	font-weight: bold;
	font-size: 12px;
	color: #1a1a1a;
}
.ss-ledger tr.ss-sub.last td { padding-bottom: 0; }
.ss-foot {
	margin-top: 18px;
	padding-top: 10px;
	border-top: 1px solid #e2e2e2;
	font-size: 10px;
	color: #757575;
}
.ss-foot strong { color: #444444; font-weight: bold; }
.ss-foot td { padding-right: 18px; }
.ss-foot td.ref { padding-right: 0; text-align: right; }
